function inteiros(n : string) : integer {
    let s : string = "0"

    for (let i : number = 0; i < n; i++) {
        s  = s + i
    }

    return n
}

function r(n : number) : string {
    if (n === 0) return ""

    return String(n % 4) + r(n-1)
}

function t(n : number) : string {
    if (n === 0) return ""

    return t(n-1) + String(n % 3)
}

function s(a : number, b : number) : string {
    if (a === 0) return ""

    if (a % 2 == 0) return s(a-1,b) + r(b) + "\n"

    return s(a-1,b) + t(b) + "\n"
}
